#' Check plot params
#'
#' @description Checkmate extension for the output of [params_plots()].
#'
#' @param x The object to check.
#'
#' @returns `TRUE` if the check was successful, otherwise a
#' checkmate-style error string.
#'
#' @keywords internal
checkPlotParams <- function(x) {
  res <- check_list_shape(
    x,
    c(
      "width",
      "height",
      "file_type",
      "unit",
      "res",
      "create_dir"
    )
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_qtest_rules(
    x,
    list(
      width = "N1",
      height = "N1",
      res = "I1",
      create_dir = "B1"
    ),
    label = "plot params",
    hint = "width, height need to be numericals and res an integer."
  )
  if (!isTRUE(res)) {
    return(res)
  }

  res <- apply_choice_rules(
    x,
    list(
      file_type = c(".png", ".pdf"),
      unit = c("in", "px", "cm")
    ),
    label = "plot params",
    hint = "width, height need to be numericals and res an integer."
  )
  if (!isTRUE(res)) {
    return(res)
  }

  return(TRUE)
}

#' Assert plot params
